INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Grundsätze (Art. 5) > Transparenz
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Fordert der Grundsatz der Transparenz gemäß Art. 5 DSGVO, dass Betroffene über die Verarbeitung ihrer Daten informiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Transparenz erfordert klare und verständliche Information"}, {"text": "Nein", "correct": false, "because": "Information ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Transparenz nach Art. 5 DSGVO ohne Datenschutzerklärung gewährleistet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Eine Datenschutzerklärung ist ein zentrales Mittel zur Transparenz"}, {"text": "Ja", "correct": false, "because": "Ohne Information fehlt Transparenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Transparenz gemäß Art. 5 DSGVO immer in schriftlicher Form erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Formen wie elektronische Hinweise sind möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verstöße gegen den Grundsatz der Transparenz zu Bußgeldern führen?', 2, '[{"text": "Ja", "correct": true, "because": "Mangelnde Transparenz kann sanktioniert werden"}, {"text": "Nein", "correct": false, "because": "Bußgelder sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Transparenz nach Art. 5 DSGVO nur für die betroffenen Personen relevant?', 2, '[{"text": "No", "correct": true, "because": "Auch Aufsichtsbehörden profitieren von Transparenz"}, {"text": "Yes", "correct": false, "because": "Breitere Relevanz besteht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt der Grundsatz der Transparenz nach Art. 5 DSGVO primär?', 2, '[{"text": "Verständliche Information der Betroffenen", "correct": true, "because": "Betroffene sollen Verarbeitung nachvollziehen"}, {"text": "Maximale Datenverarbeitung", "correct": false, "because": "Kein Ziel"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel wird am häufigsten genutzt, um Transparenz gemäß Art. 5 DSGVO sicherzustellen?', 3, '[{"text": "Datenschutzerklärung", "correct": true, "because": "Pflichtdokument für Informationen"}, {"text": "E-Mail-Benachrichtigung", "correct": false, "because": "Situativ"}, {"text": "Telefonische Auskunft", "correct": false, "because": "Weniger praktikabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung stellt die Transparenz nach Art. 5 DSGVO an die Kommunikation?', 2, '[{"text": "Verständlichkeit", "correct": true, "because": "Informationen müssen klar und einfach sein"}, {"text": "Technische Präzision", "correct": false, "because": "Sekundär"}, {"text": "Schnelligkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei fehlender Transparenz nach Art. 5 DSGVO?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstöße können sanktioniert werden"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information muss gemäß Art. 5 DSGVO transparent bereitgestellt werden?', 2, '[{"text": "Zweck der Datenverarbeitung", "correct": true, "because": "Betroffene müssen Zweck kennen"}, {"text": "Serverstandort", "correct": false, "because": "Nicht zwingend"}, {"text": "Softwareversion", "correct": false, "because": "Nicht vorgeschrieben"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente der Transparenz sind nach Art. 5 DSGVO erforderlich?', 4, '[{"text": "Verständliche Sprache", "correct": true, "because": "Klarheit für Betroffene"}, {"text": "Information über Zwecke", "correct": true, "because": "Transparenz über Verwendung"}, {"text": "Angaben zur Identität des Verantwortlichen", "correct": true, "because": "Verantwortlicher muss bekannt sein"}, {"text": "Maximale technische Details", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mittel können Transparenz gemäß Art. 5 DSGVO sicherstellen?', 3, '[{"text": "Datenschutzerklärung", "correct": true, "because": "Hauptinstrument"}, {"text": "Informationspflichten", "correct": true, "because": "Pflicht bei Datenerhebung"}, {"text": "Einwilligungstexte", "correct": true, "because": "Klare Kommunikation"}, {"text": "Software-Updates", "correct": false, "because": "Kein Transparenzmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen müssen gemäß Art. 5 DSGVO transparent bereitgestellt werden?', 4, '[{"text": "Zweck der Verarbeitung", "correct": true, "because": "Betroffene müssen Zweck kennen"}, {"text": "Rechtsgrundlage", "correct": true, "because": "Legitimation erforderlich"}, {"text": "Empfänger der Daten", "correct": true, "because": "Weitergabe muss offengelegt werden"}, {"text": "Hardware-Spezifikationen", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen den Grundsatz der Transparenz haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Sanktionen bei Verstößen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kunden verlieren Vertrauen"}, {"text": "Schadensersatzforderungen", "correct": true, "because": "Betroffene können klagen"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt Art. 5 DSGVO an die Transparenz?', 3, '[{"text": "Verständlichkeit", "correct": true, "because": "Klarheit für Laien"}, {"text": "Zugänglichkeit", "correct": true, "because": "Einfacher Zugang zu Informationen"}, {"text": "Aktualität", "correct": true, "because": "Informationen müssen aktuell sein"}, {"text": "Minimale Offenlegung", "correct": false, "because": "Vollständigkeit erforderlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Transparenz nach Art. 5 DSGVO erfordert eine Datenschutzerklärung. b) Sie kann ohne schriftliche Form gewährleistet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenschutzerklärung ja, Schriftform üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist unpraktisch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Transparenz bedeutet verständliche Information für Betroffene. b) Sie ist nur für Behörden relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verständlichkeit ja, Betroffene im Fokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verstöße gegen Transparenz können Bußgelder nach sich ziehen. b) Transparenz erfordert immer schriftliche Form.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, Form flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Zweck der Verarbeitung muss transparent offengelegt werden. b) Transparenz gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweck ja, alle Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Transparenz erfordert Angaben zum Verantwortlichen. b) Sie ist ohne Datenschutzerklärung unmöglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verantwortlicher ja, Erklärung nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

